var bits = require('bit-twiddle');

function fft(dir, nrows, ncols, buffer, x_ptr, y_ptr, scratch_ptr) {
  dir |= 0;
  nrows |= 0;
  ncols |= 0;
  x_ptr |= 0;
  y_ptr |= 0;

  if (bits.isPow2(ncols)) {
    fftRadix2(dir, nrows, ncols, buffer, x_ptr, y_ptr);
  } else {
    fftBluestein(dir, nrows, ncols, buffer, x_ptr, y_ptr, scratch_ptr);
  }
}

module.exports = fft;

function scratchMemory(n) {
  if (bits.isPow2(n)) {
    return 0;
  }

  return 2 * n + 4 * bits.nextPow2(2 * n + 1);
}

module.exports.scratchMemory = scratchMemory; //Radix 2 FFT Adapted from Paul Bourke's C Implementation

function fftRadix2(dir, nrows, ncols, buffer, x_ptr, y_ptr) {
  dir |= 0;
  nrows |= 0;
  ncols |= 0;
  x_ptr |= 0;
  y_ptr |= 0;
  var nn, m, i, i1, j, k, i2, l, l1, l2;
  var c1, c2, t, t1, t2, u1, u2, z, row, a, b, c, d, k1, k2, k3; // Calculate the number of points

  nn = ncols;
  m = bits.log2(nn);

  for (row = 0; row < nrows; ++row) {
    // Do the bit reversal
    i2 = nn >> 1;
    j = 0;

    for (i = 0; i < nn - 1; i++) {
      if (i < j) {
        t = buffer[x_ptr + i];
        buffer[x_ptr + i] = buffer[x_ptr + j];
        buffer[x_ptr + j] = t;
        t = buffer[y_ptr + i];
        buffer[y_ptr + i] = buffer[y_ptr + j];
        buffer[y_ptr + j] = t;
      }

      k = i2;

      while (k <= j) {
        j -= k;
        k >>= 1;
      }

      j += k;
    } // Compute the FFT


    c1 = -1.0;
    c2 = 0.0;
    l2 = 1;

    for (l = 0; l < m; l++) {
      l1 = l2;
      l2 <<= 1;
      u1 = 1.0;
      u2 = 0.0;

      for (j = 0; j < l1; j++) {
        for (i = j; i < nn; i += l2) {
          i1 = i + l1;
          a = buffer[x_ptr + i1];
          b = buffer[y_ptr + i1];
          c = buffer[x_ptr + i];
          d = buffer[y_ptr + i];
          k1 = u1 * (a + b);
          k2 = a * (u2 - u1);
          k3 = b * (u1 + u2);
          t1 = k1 - k3;
          t2 = k1 + k2;
          buffer[x_ptr + i1] = c - t1;
          buffer[y_ptr + i1] = d - t2;
          buffer[x_ptr + i] += t1;
          buffer[y_ptr + i] += t2;
        }

        k1 = c1 * (u1 + u2);
        k2 = u1 * (c2 - c1);
        k3 = u2 * (c1 + c2);
        u1 = k1 - k3;
        u2 = k1 + k2;
      }

      c2 = Math.sqrt((1.0 - c1) / 2.0);

      if (dir < 0) {
        c2 = -c2;
      }

      c1 = Math.sqrt((1.0 + c1) / 2.0);
    } // Scaling for inverse transform


    if (dir < 0) {
      var scale_f = 1.0 / nn;

      for (i = 0; i < nn; i++) {
        buffer[x_ptr + i] *= scale_f;
        buffer[y_ptr + i] *= scale_f;
      }
    } // Advance pointers


    x_ptr += ncols;
    y_ptr += ncols;
  }
} // Use Bluestein algorithm for npot FFTs
// Scratch memory required:  2 * ncols + 4 * bits.nextPow2(2*ncols + 1)


function fftBluestein(dir, nrows, ncols, buffer, x_ptr, y_ptr, scratch_ptr) {
  dir |= 0;
  nrows |= 0;
  ncols |= 0;
  x_ptr |= 0;
  y_ptr |= 0;
  scratch_ptr |= 0; // Initialize tables

  var m = bits.nextPow2(2 * ncols + 1),
      cos_ptr = scratch_ptr,
      sin_ptr = cos_ptr + ncols,
      xs_ptr = sin_ptr + ncols,
      ys_ptr = xs_ptr + m,
      cft_ptr = ys_ptr + m,
      sft_ptr = cft_ptr + m,
      w = -dir * Math.PI / ncols,
      row,
      a,
      b,
      c,
      d,
      k1,
      k2,
      k3,
      i;

  for (i = 0; i < ncols; ++i) {
    a = w * (i * i % (ncols * 2));
    c = Math.cos(a);
    d = Math.sin(a);
    buffer[cft_ptr + (m - i)] = buffer[cft_ptr + i] = buffer[cos_ptr + i] = c;
    buffer[sft_ptr + (m - i)] = buffer[sft_ptr + i] = buffer[sin_ptr + i] = d;
  }

  for (i = ncols; i <= m - ncols; ++i) {
    buffer[cft_ptr + i] = 0.0;
  }

  for (i = ncols; i <= m - ncols; ++i) {
    buffer[sft_ptr + i] = 0.0;
  }

  fftRadix2(1, 1, m, buffer, cft_ptr, sft_ptr); //Compute scale factor

  if (dir < 0) {
    w = 1.0 / ncols;
  } else {
    w = 1.0;
  } //Handle direction


  for (row = 0; row < nrows; ++row) {
    // Copy row into scratch memory, multiply weights
    for (i = 0; i < ncols; ++i) {
      a = buffer[x_ptr + i];
      b = buffer[y_ptr + i];
      c = buffer[cos_ptr + i];
      d = -buffer[sin_ptr + i];
      k1 = c * (a + b);
      k2 = a * (d - c);
      k3 = b * (c + d);
      buffer[xs_ptr + i] = k1 - k3;
      buffer[ys_ptr + i] = k1 + k2;
    } //Zero out the rest


    for (i = ncols; i < m; ++i) {
      buffer[xs_ptr + i] = 0.0;
    }

    for (i = ncols; i < m; ++i) {
      buffer[ys_ptr + i] = 0.0;
    } // FFT buffer


    fftRadix2(1, 1, m, buffer, xs_ptr, ys_ptr); // Apply multiplier

    for (i = 0; i < m; ++i) {
      a = buffer[xs_ptr + i];
      b = buffer[ys_ptr + i];
      c = buffer[cft_ptr + i];
      d = buffer[sft_ptr + i];
      k1 = c * (a + b);
      k2 = a * (d - c);
      k3 = b * (c + d);
      buffer[xs_ptr + i] = k1 - k3;
      buffer[ys_ptr + i] = k1 + k2;
    } // Inverse FFT buffer


    fftRadix2(-1, 1, m, buffer, xs_ptr, ys_ptr); // Copy result back into x/y

    for (i = 0; i < ncols; ++i) {
      a = buffer[xs_ptr + i];
      b = buffer[ys_ptr + i];
      c = buffer[cos_ptr + i];
      d = -buffer[sin_ptr + i];
      k1 = c * (a + b);
      k2 = a * (d - c);
      k3 = b * (c + d);
      buffer[x_ptr + i] = w * (k1 - k3);
      buffer[y_ptr + i] = w * (k1 + k2);
    }

    x_ptr += ncols;
    y_ptr += ncols;
  }
}